    let galleryConfig = { baseUrl: '', token: '' };
    let remoteImages = [];
    let remoteGalleryLoaded = false;
    let themeTimer = null;
    let feedbackTimer = null;
    let menuTimer = null;
    let menuDelay = null;
    let generationBusy = false;
    let generationController = null;
    let generationEpoch = 0;
    const activities = new Map();
    let activityCounter = 0;
    let uiNotice = null;

    function showCapsule(message, type = 'info') {
        if(destroyed)return;
        uiNotice={message:String(message),type};recordMintFeedback(message,type);
        clearTimeout(feedbackTimer);feedbackTimer=null;renderCapsule();
    }
    function renderCapsule() {
        if(destroyed){targetDoc.getElementById('mint-feedback')?.remove();return;}
        let box=targetDoc.getElementById('mint-feedback');
        if(!box){box=targetDoc.createElement('div');box.id='mint-feedback';box.setAttribute('role','status');box.setAttribute('aria-live','polite');targetDoc.body.appendChild(box);}
        const jobs=[...activities.values()];const busy=jobs.length>0;
        const notice=uiNotice;const type=busy?'info':notice?.type || 'info';
        box.hidden=!busy&&!notice;mountMintFeedback(box);scheduleMintNotice();if(box.hidden)return;
        box.classList.toggle('is-busy',busy);box.dataset.type=type;box.dataset.theme=isDayTime()?'day':'night';box.replaceChildren();
        if(type==='error'){box.setAttribute('role','alert');box.setAttribute('aria-live','assertive');}else{box.setAttribute('role','status');box.setAttribute('aria-live','polite');}
        const avatar=targetDoc.createElement('img');avatar.className='mint-toast-avatar';avatar.alt=type==='error'?'哭哭脸的小序':type==='success'?'开心的小序':'小序';
        avatar.src=type==='error'?XUBAI_ERROR_AVATAR:type==='success'||type==='egg'?XUBAI_SUCCESS_AVATAR:isDayTime()?MINT_DAY_AVATAR:MINT_NIGHT_AVATAR;
        const copy=targetDoc.createElement('div');copy.className='mint-toast-copy';const title=targetDoc.createElement('strong');
        title.textContent=busy?'小序正在努力…':type==='error'?'出错了，请重试':type==='success'?(notice.message.includes('生成完成')?'生成成功':'操作完成'):type==='egg'?'小白的秘密纸条':'小序提示';
        const message=targetDoc.createElement('div');message.className='mint-toast-message';message.textContent=busy?`${jobs[jobs.length-1]}${jobs.length>1?' · '+jobs.length+' 项任务':''}`:notice.message;
        if(busy)title.prepend(mintSpinner());copy.append(title,message);box.append(avatar,copy);
        if(!busy){
            const controls=targetDoc.createElement('div');controls.className='mint-toast-actions';
            if(type==='error'){const button=targetDoc.createElement('button');button.textContent='复制';button.setAttribute('aria-label','复制错误信息');button.addEventListener('click',()=>copyMintMessage(notice.message));controls.appendChild(button);}
            const close=targetDoc.createElement('button');close.innerHTML=extendedMintIcon('close');close.setAttribute('aria-label','关闭提示');close.addEventListener('click',()=>{uiNotice=null;renderCapsule();});controls.appendChild(close);box.appendChild(controls);
        }
        positionMintFeedback();
    }

    function startActivity(label) {
        const id = ++activityCounter; activities.set(id, label); renderCapsule();
        return () => { activities.delete(id); renderCapsule(); };
    }
    function on(el, type, handler, options) {
        el.addEventListener(type, async function(e) {
            const isAction = type === 'click' || type === 'change';
            const navigation=el.hasAttribute?.('data-page')||el.hasAttribute?.('data-go');
            const label = (el.textContent || el.getAttribute('aria-label') || '正在处理').trim().slice(0, 28);
            if (isAction && el.dataset.mintBusy === '1') return;
            const oldDisabled = el.disabled;
            let finish = null;
            try {
                if (isAction) {
                    el.classList.remove('mint-tap'); void el.offsetWidth; el.classList.add('mint-tap');
                    if(!navigation&&uiPrefs.showClickNotices)showCapsule(type === 'click' ? `已点击 · ${label || '操作'}` : '正在应用更改');
                }
                const noticeBefore = uiNotice;
                const result = handler.call(this, e);
                if (result && typeof result.then === 'function') {
                    if (isAction) {
                        el.dataset.mintBusy = '1';
                        if (el.tagName === 'BUTTON') el.disabled = true;
                        el.setAttribute('aria-busy', 'true');
                        if(el.tagName==='BUTTON'&&!el.querySelector('.mint-loading-ring'))el.prepend(mintSpinner());
                        finish = startActivity((label || '操作') + ' · 处理中…');
                    }
                    await result;
                    if (isAction && uiPrefs.showClickNotices && !navigation && uiNotice === noticeBefore) showCapsule('操作已结束');
                }
            } catch (error) {
                toast(error?.message || String(error), 'error');
            } finally {
                if (finish) finish();
                delete el.dataset.mintBusy; el.removeAttribute('aria-busy');el.querySelector?.('.mint-loading-ring')?.remove();
                if (el.tagName === 'BUTTON' && !el.dataset.generationLock) el.disabled = oldDisabled;
            }
        }, options);
    }
    const THEME_CONFIG_KEY='__mint_theme__';
    const DEFAULT_THEME_PREFS={mode:'auto',dayStart:'08:00',dayEnd:'00:00'};
    let themePrefs={...DEFAULT_THEME_PREFS};
    function timeToMinutes(value) {
        const match=/^(\d{2}):(\d{2})$/.exec(String(value));
        if(!match||Number(match[1])>23||Number(match[2])>59)return null;
        return Number(match[1])*60+Number(match[2]);
    }
    function normalizeThemePrefs(value) {
        const prefs={...DEFAULT_THEME_PREFS,...(value&&typeof value==='object'?value:{})};
        if(!['auto','day','night'].includes(prefs.mode))prefs.mode='auto';
        if(timeToMinutes(prefs.dayStart)===null||timeToMinutes(prefs.dayEnd)===null||prefs.dayStart===prefs.dayEnd){prefs.dayStart='08:00';prefs.dayEnd='00:00';}
        return {mode:prefs.mode,dayStart:prefs.dayStart,dayEnd:prefs.dayEnd};
    }
    function isDayTime(date=new Date()) {
        if(themePrefs.mode==='day')return true;
        if(themePrefs.mode==='night')return false;
        const start=timeToMinutes(themePrefs.dayStart),end=timeToMinutes(themePrefs.dayEnd);
        const now=date.getHours()*60+date.getMinutes();
        return start<end?now>=start&&now<end:now>=start||now<end;
    }
    function themeScheduleLabel() {
        const end=themePrefs.dayEnd==='00:00'?'24:00':themePrefs.dayEnd;
        const overnight=timeToMinutes(themePrefs.dayEnd)<timeToMinutes(themePrefs.dayStart)&&themePrefs.dayEnd!=='00:00';
        return themePrefs.dayStart+'–'+(overnight?'次日 ':'')+end;
    }
    function syncThemeControls(panel,resetTimes=true) {
        const auto=panel.querySelector('#mint-theme-auto');if(auto)auto.checked=themePrefs.mode==='auto';
        if(resetTimes){panel.querySelector('#mint-theme-start').value=themePrefs.dayStart;panel.querySelector('#mint-theme-end').value=themePrefs.dayEnd;}
        const status=panel.querySelector('#mint-theme-status');if(status)status.textContent=(themePrefs.mode==='auto'?'自动切换 · 日间 '+themeScheduleLabel():'手动'+(isDayTime()?'日间':'夜间')+' · 自动切换已关闭');
    }
    async function saveThemePrefs(next) {
        const normalized=normalizeThemePrefs(next);
        await saveConfig(THEME_CONFIG_KEY,normalized);themePrefs=normalized;applyMintTheme();
        const panel=targetDoc.getElementById('aibar-panel');if(panel)syncThemeControls(panel,false);
    }
    function applyMintTheme() {
        const day=isDayTime();const feedback=targetDoc.getElementById('mint-feedback');if(feedback)renderCapsule();
        const modal=targetDoc.getElementById('mint-confirm');if(modal)modal.dataset.theme=day?'day':'night';
        const panel=targetDoc.getElementById('aibar-panel');if(!panel)return;
        panel.dataset.theme=day?'day':'night';
        const avatar=panel.querySelector('#mint-mascot');if(avatar&&avatar.dataset.mode!==panel.dataset.theme){avatar.dataset.mode=panel.dataset.theme;avatar.src=day?MINT_DAY_AVATAR:MINT_NIGHT_AVATAR;}
        const mini=panel.querySelector('#mint-mini-avatar');if(mini&&mini.dataset.mode!==panel.dataset.theme){mini.src=day?MINT_DAY_AVATAR:MINT_NIGHT_AVATAR;mini.dataset.mode=panel.dataset.theme;}
        const toggle=panel.querySelector('#mint-theme-toggle');
        if(toggle){toggle.innerHTML=mintIcon(day?'sun':'moon')+(themePrefs.mode==='auto'?'<span class="mint-auto-badge">自</span>':'');toggle.setAttribute('aria-label',`当前${themePrefs.mode==='auto'?'自动':'手动'}${day?'日间':'夜间'}，点击切换为${day?'夜间':'日间'}并关闭自动切换`);toggle.setAttribute('aria-pressed',String(!day));toggle.title=themePrefs.mode==='auto'?'自动切换中；点击手动换色':'手动模式；设置中可重新开启自动切换';}
        const clock=panel.querySelector('#mint-clock');if(clock)clock.textContent=`${day?'日间':'夜间'} · ${themePrefs.mode==='auto'?'自动':'手动'} · ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})}`;
        const greeting=panel.querySelector('#mint-greeting');if(greeting)greeting.textContent=day?'陪你把灵感变可爱。':'夜间工作台已就位，慢慢来。';
        const status=panel.querySelector('#mint-theme-status');if(status)status.textContent=themePrefs.mode==='auto'?'自动切换 · 日间 '+themeScheduleLabel():'手动'+(day?'日间':'夜间')+' · 自动切换已关闭';
    }
    function bindThemeControls(panel) {
        syncThemeControls(panel);
        on(panel.querySelector('#mint-theme-toggle'),'click',async()=>{
            const mode=isDayTime()?'night':'day';await saveThemePrefs({...themePrefs,mode});
            toast(`已切换${mode==='day'?'日间':'夜间'}；自动切换已关闭。可以在设置里重新开启。`,'info');
        });
        on(panel.querySelector('#mint-theme-auto'),'change',async e=>{
            const mode=e.target.checked?'auto':isDayTime()?'day':'night';
            try{await saveThemePrefs({...themePrefs,mode});toast(mode==='auto'?'已按设置的时段自动切换':'已关闭自动切换，保持当前主题','success');}
            catch(error){syncThemeControls(panel,false);throw error;}
        });
        on(panel.querySelector('#mint-theme-save'),'click',async()=>{
            const dayStart=panel.querySelector('#mint-theme-start').value,dayEnd=panel.querySelector('#mint-theme-end').value;
            if(timeToMinutes(dayStart)===null||timeToMinutes(dayEnd)===null)throw new Error('请选择有效的开始和结束时间');
            if(dayStart===dayEnd)throw new Error('开始和结束时间不能相同；如果想全天固定一种主题，请关闭自动切换后用顶部图标选择');
            await saveThemePrefs({...themePrefs,dayStart,dayEnd});toast('时段已保存 · 日间 '+themeScheduleLabel()+(themePrefs.mode==='auto'?'':'；当前仍为手动模式'),'success');
        });
    }

