    async function persistSessionImages() {
        if (!session?.historyId) return;
        await addHistory({ ...session, id: session.historyId, ts: session.historyTs });
    }
    function syncGenerationUI() {
        const panel = targetDoc.getElementById('aibar-panel'); if (!panel) return;
        for (const id of ['ab-generate', 'ab-revise-btn', 'ab-variant-btn']) {
            const button = panel.querySelector('#' + id); if (!button) continue;
            button.disabled = generationBusy;
            if (generationBusy) { button.dataset.generationLock = '1'; button.setAttribute('aria-busy', 'true');if(!button.querySelector('.mint-loading-ring'))button.prepend(mintSpinner()); }
            else { delete button.dataset.generationLock; button.removeAttribute('aria-busy');button.querySelector('.mint-loading-ring')?.remove(); }
        }
        panel.querySelector('#mint-cancel-generation').hidden = !generationBusy;
        if (generationBusy) setStatusIfOpen('正在生成，关闭面板也会继续。');
    }
    function stripEmbeddedData(text) {
        return String(text || '').replace(/data:[^\s"'<>)]*;base64,[A-Za-z0-9+/=\r\n]+/gi, '{{IMG:removed_inline_asset}}');
    }
    async function receiveGeneration(promise, signal) {
        let timer, abort;
        const stop = new Promise((_, reject) => {
            abort = () => reject(new Error('已取消接收生成结果'));
            if (signal.aborted) return abort();
            signal.addEventListener('abort', abort, { once: true });
            timer = setTimeout(() => { generationController?.abort(); reject(new Error('生成等待超过 4 分钟')); }, 240000);
        });
        try { return await Promise.race([promise, stop]); }
        finally { clearTimeout(timer); signal.removeEventListener('abort', abort); }
    }
    async function modelFetch(url, options = {}) {
        const controller = generationController || new AbortController();
        const timer = setTimeout(() => controller.abort(), 240000);
        try { return await fetch(url, { ...options, signal: controller.signal }); }
        catch (e) { if (e.name === 'AbortError') throw new Error('生成已取消或请求超时'); throw e; }
        finally { clearTimeout(timer); }
    }
    function apiEndpoint(base, suffix) {
        const clean = base.replace(/\/+$/, '').replace(/\/(chat\/completions|models|messages)$/, '');
        return clean + (/\/v\d+(?:beta\d*)?$/.test(clean) ? '' : '/v1') + '/' + suffix;
    }

