    function switchMintPage(panel, page, announce = true) {
        if (!['create','gallery','history','settings'].includes(page)) return;
        const scroll = panel.querySelector('#mint-scroll');
        pageScroll.set(currentPage, scroll.scrollTop); currentPage = page;
        panel.querySelectorAll('[data-mint-page]').forEach(section => { section.hidden = section.dataset.mintPage !== page; });
        panel.querySelectorAll('[data-page]').forEach(button => { button.setAttribute('aria-selected',String(button.dataset.page === page)); button.tabIndex = button.dataset.page === page ? 0 : -1; });
        scroll.scrollTop = pageScroll.get(page) || 0;
        if(page==='gallery'){renderRemoteGallery(panel).catch(e=>toast(e.message,'error'));renderImagePlan(panel).catch(e=>toast(e.message,'error'));}
        if(page==='settings')updateConnectionOverview(panel);
        if (page === 'history') renderHistory(panel).catch(e => toast(e.message,'error'));
        if (announce && uiPrefs.showPageNotices) showCapsule(({create:'回到创作台',gallery:'打开图片收藏室',history:'打开灵感存档',settings:'打开设置'})[page]);
    }
    function updateConnectionLabel(panel) {
        const source = panel.querySelector('#ab-source'); const label = panel.querySelector('#mint-source-label');
        if (label) label.textContent = source.value === 'custom' ? '当前连接 · ' + (panel.querySelector('#ab-config-select').value || '请到设置选择 API') : '当前连接 · 酒馆已选模型';
    }
    function bindOtomePanel(panel) {
        panel.querySelectorAll('[data-page]').forEach(button => on(button,'click',()=>switchMintPage(panel,button.dataset.page)));
        panel.querySelectorAll('[data-go]').forEach(button => on(button,'click',()=>{
            switchMintPage(panel,button.dataset.go);
            if (button.textContent.includes('字体')) { panel.querySelector('#ab-font-details').open=true; panel.querySelector('#ab-font-details').scrollIntoView({block:'start',behavior:'smooth'}); }
        }));
        panel.querySelector('#mint-tabs').addEventListener('keydown',e=>{
            if (!['ArrowLeft','ArrowRight','Home','End'].includes(e.key)) return;
            e.preventDefault(); const pages=['create','gallery','history','settings']; const at=pages.indexOf(currentPage);
            const index=e.key==='Home'?0:e.key==='End'?3:(at+(e.key==='ArrowRight'?1:3))%4;
            switchMintPage(panel,pages[index]);panel.querySelector('#mint-tab-'+pages[index]).focus();
        });
        panel.querySelectorAll('[data-prompt]').forEach(button=>on(button,'click',()=>{
            const input=panel.querySelector('#ab-desc');input.value=[input.value.trim(),button.dataset.prompt].filter(Boolean).join('，');input.focus();showCapsule('已把风格词添进描述');
        }));
        const pet=()=>{
            const now=Date.now();avatarTapTimes=avatarTapTimes.filter(t=>now-t<5000);avatarTapTimes.push(now);
            if (avatarTapTimes.length>=5) { avatarTapTimes=[];showCapsule(['发现了？这里住着一只没有工资的程序员。','汪。……等等，串台了。我是写代码的那个小白。','银白头发不是加班造成的，原装就是这样。','你负责冒出想法，我负责把小玩意做出来。'][Math.floor(Math.random()*4)],'egg'); }
            else showCapsule('摸到了，小序收到。');
        };
        on(panel.querySelector('#mint-header-avatar'),'click',pet);on(panel.querySelector('#mint-hero-avatar'),'click',pet);
        on(panel.querySelector('#mint-demo-success'),'click',()=>showCapsule('做好了，快看看。这次可以摸一下头吗？','success'));
        on(panel.querySelector('#mint-demo-error'),'click',()=>showCapsule('这是报错样式演示，没有发生真实故障。线索会显示在这里，并且可以复制。','error'));
        on(panel.querySelector('#mint-gallery-refresh'),'click',async()=>{
            const data=await refreshSavedGallery(true);if(data)toast('图库已刷新','success');else if(galleryConnectionNote.startsWith('自动连接未完成'))throw new Error(galleryConnectionNote);
        });
        on(panel.querySelector('#mint-gallery-search'),'input',()=>renderRemoteGallery(panel));
        panel.addEventListener('change',()=>updateConnectionLabel(panel));
        bindThemeControls(panel);
        bindUiPrefs(panel);
        switchMintPage(panel,currentPage,false);updateConnectionLabel(panel);
    }
